-- Group chats, broadcast channels, media metadata, pins and typing.
CREATE TABLE message_spaces (id INTEGER PRIMARY KEY AUTOINCREMENT,type TEXT NOT NULL CHECK(type IN ('group','channel')),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',username TEXT UNIQUE,owner_id INTEGER NOT NULL REFERENCES users(id),is_public INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX message_spaces_type ON message_spaces(type,updated_at DESC);
CREATE TABLE message_space_members (space_id INTEGER NOT NULL REFERENCES message_spaces(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL DEFAULT 'member' CHECK(role IN ('owner','admin','member')),joined_at INTEGER NOT NULL,PRIMARY KEY(space_id,user_id)) WITHOUT ROWID;
CREATE INDEX space_members_user ON message_space_members(user_id,joined_at DESC);
CREATE TABLE message_attachments (id INTEGER PRIMARY KEY AUTOINCREMENT,owner_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,thread_id INTEGER REFERENCES dm_threads(id) ON DELETE CASCADE,space_id INTEGER REFERENCES message_spaces(id) ON DELETE CASCADE,object_key TEXT NOT NULL UNIQUE,filename TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE message_space_messages (id INTEGER PRIMARY KEY AUTOINCREMENT,space_id INTEGER NOT NULL REFERENCES message_spaces(id) ON DELETE CASCADE,sender_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,body TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL DEFAULT 'text',attachment_id INTEGER REFERENCES message_attachments(id) ON DELETE SET NULL,reply_to_id INTEGER REFERENCES message_space_messages(id) ON DELETE SET NULL,forwarded_from INTEGER REFERENCES message_space_messages(id) ON DELETE SET NULL,edited_at INTEGER,deleted_at INTEGER,pinned_at INTEGER,created_at INTEGER NOT NULL);
CREATE INDEX space_messages_history ON message_space_messages(space_id,id DESC);
CREATE TABLE dm_pins (thread_id INTEGER NOT NULL REFERENCES dm_threads(id) ON DELETE CASCADE,message_id INTEGER NOT NULL REFERENCES dm_messages(id) ON DELETE CASCADE,pinned_by INTEGER NOT NULL REFERENCES users(id),pinned_at INTEGER NOT NULL,PRIMARY KEY(thread_id,message_id)) WITHOUT ROWID;
CREATE TABLE space_pins (space_id INTEGER NOT NULL REFERENCES message_spaces(id) ON DELETE CASCADE,message_id INTEGER NOT NULL REFERENCES message_space_messages(id) ON DELETE CASCADE,pinned_by INTEGER NOT NULL REFERENCES users(id),pinned_at INTEGER NOT NULL,PRIMARY KEY(space_id,message_id)) WITHOUT ROWID;
CREATE TABLE message_typing (scope TEXT NOT NULL CHECK(scope IN ('dm','space')),scope_id INTEGER NOT NULL,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,updated_at INTEGER NOT NULL,PRIMARY KEY(scope,scope_id,user_id)) WITHOUT ROWID;
CREATE INDEX typing_expiry ON message_typing(updated_at);
